+ {x:18,y:18,w:300,h:204,name:"DAD'S ROOM",emoji:'🛏️',floor:'#d9e8d6'},
+ {x:18,y:238,w:300,h:344,name:'GIRLS’ ROOM',emoji:'🧸',floor:'#f1dfe0'},
+ {x:332,y:18,w:295,h:264,name:'BATHROOM',emoji:'🫧',floor:'#d9e9e9'},
+ {x:332,y:298,w:295,h:284,name:'KITCHEN',emoji:'🍳',floor:'#f2e7ce'},
+ {x:641,y:18,w:301,h:564,name:'LIVING ROOM',emoji:'🛋️',floor:'#e7dfd1'}
+];
+const dad={x:170,y:135,dir:1,walk:0};
+const girls=[
+ {name:'Elaina',age:12,x:133,y:320,color:'#6685bd',hair:'#49382f',focus:72,mood:'sleepy',emoji:'😴',agenda:'still asleep',awake:false,bed:{x:115,y:286},goal:null},
+ {name:'Elsie',age:9,x:230,y:370,color:'#e68d83',hair:'#69452f',focus:65,mood:'sleepy',emoji:'😴',agenda:'still asleep',awake:false,bed:{x:220,y:286},goal:null},
+ {name:'Ellerie',age:5,x:145,y:492,color:'#e6b24f',hair:'#8b5a2c',focus:82,mood:'sleepy',emoji:'😴',agenda:'still asleep',awake:false,bed:{x:140,y:422},goal:null}
+];
+const charlie={x:575,y:410,visible:true,nap:false};
+const chores=[
+ {id:'breakfast',label:'Make breakfast',emoji:'🥞',room:'KITCHEN',x:552,y:350,time:'7:30',desc:'Breakfast is served! Everyone eats. Sir is a household hero.'},
+ {id:'showers',label:'Morning showers',emoji:'🚿',room:'BATHROOM',x:540,y:153,time:'8:15',desc:'All three girls are clean, if not entirely dry.'},
+ {id:'laundry',label:'Start laundry',emoji:'🧺',room:'BATHROOM',x:390,y:191,time:'9:00',desc:'Laundry is humming. Someone put a toy in the washer.'},
+ {id:'dishes1',label:'Wash breakfast dishes',emoji:'🍽️',room:'KITCHEN',x:460,y:385,time:'9:30',desc:'The dishes are done. The sink is briefly visible.'},
+ {id:'lunch',label:'Make lunch',emoji:'🥪',room:'KITCHEN',x:552,y:350,time:'12:00',desc:'Lunch! Even Charlie is impressed.'},
+ {id:'dishes2',label:'Wash lunch dishes',emoji:'🫧',room:'KITCHEN',x:460,y:385,time:'1:00',desc:'Lunch dishes cleared. The afternoon is yours.'},
+ {id:'tidy',label:'Tidy the living room',emoji:'🧸',room:'LIVING ROOM',x:766,y:424,time:'3:00',desc:'The floor emerges from a sea of toys. Briefly.'},
+ {id:'dinner',label:'Make dinner',emoji:'🍝',room:'KITCHEN',x:552,y:350,time:'6:00',desc:'Dinner is on the table. Everyone ate something green.'},
+ {id:'dishes3',label:'Wash dinner dishes',emoji:'🍽️',room:'KITCHEN',x:460,y:385,time:'7:00',desc:'Kitchen reset. One last push, Sir.'},
+ {id:'bedtime',label:'Get everyone tucked in',emoji:'🌙',room:'GIRLS’ ROOM',x:175,y:286,time:'8:00',desc:'All three girls are tucked in and the house is quiet.'}
+];
+let choreIndex=0,started=false,ended=false,mins=7*60,energy=75,stress=12,temperOutbursts=0,helped=0,walkFrame=0,toastTimer=0,activeTarget=null,lastTick=performance.now(),gameSeconds=0,interacted=0;
+const keys={};
+const moodSet={happy:['😊','happy'],frustrated:['😤','frustrated'],focused:['🎯','focused'],distracted:['🌀','distracted'],loving:['💛','loving'],excited:['🤩','excited'],sleepy:['😴','sleepy'],silly:['🤪','silly'],calm:['😌','calm']};
+function say(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');toastTimer=2.7}
+function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
+function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
+function current(){return chores[chores.length===choreIndex?chores.length-1:choreIndex]}
+function zoneAt(x,y){return rooms.find(r=>x>r.x&&x<r.x+r.w&&y>r.y&&y<r.y+r.h)}
+function setMood(g,m,agenda){g.mood=m;g.emoji=moodSet[m][0];if(agenda)g.agenda=agenda}
+function updateGirls(dt){
+ if(!started||ended)return;
+ const clockMins=mins;
+ girls.forEach((g,i)=>{
+  if(!g.awake&&clockMins>=420+i*22){g.awake=true;g.x=g.bed.x;g.y=g.bed.y+35;g.goal=null;setMood(g,'silly',['Plotting breakfast negotiations','Looking for her favorite book','Ready to take on the world'][i]);say(`${g.name} is up! She calls Dad “Captain Crumbs.”`)}
+  if(!g.awake)return;
+  g.focus=clamp(g.focus-dt*(g.mood==='distracted'?1.8:.35),8,100);
+  if(g.focus<30&&g.mood!=='distracted'&&g.mood!=='sleepy')setMood(g,'frustrated','needs a little break');
+  if(g.mood==='sleepy'&&clockMins<1260)return;
+  if(!g.goal||distance(g,g.goal)<5){
+   let pick=Math.random();
+   if(clockMins>=1260){g.goal={x:g.bed.x,y:g.bed.y+16};setMood(g,'sleepy','heading to bed')}
+   else if(pick<.21){g.goal=[{x:730,y:130},{x:838,y:150},{x:720,y:365}][i];setMood(g,'distracted',['TV time!','A very important book','Toy kingdom'][i])}
+   else if(pick<.34&&i===2){g.goal={x:906,y:538};setMood(g,'excited','making a break for the yard!')}
+   else {g.goal={x:460+Math.random()*110,y:350+Math.random()*110};setMood(g,g.focus>60?'focused':'silly',g.focus>60?'helping a little':'thinking up a scheme')}
+  }
+  if(g.goal){let d=distance(g,g.goal);if(d>2){let sp=20+(g.focus/100)*10;g.x+=(g.goal.x-g.x)/d*sp*dt;g.y+=(g.goal.y-g.y)/d*sp*dt}}
+  if(g.mood==='distracted'&&Math.random()<dt*.018)g.focus=clamp(g.focus+5,0,100);
+ });
+ if(charlie.visible&&Math.random()<dt*.025){charlie.x=clamp(charlie.x+(Math.random()-.5)*100,660,910);charlie.y=clamp(charlie.y+(Math.random()-.5)*100,370,545);if(Math.random()<.3)say('Charlie has relocated to the most inconvenient spot.');}
