  ctx.save();ctx.globalAlpha=.13;ctx.strokeStyle='#8c806c';ctx.lineWidth=1;
  for(let y=r.y+22;y<r.y+r.h;y+=34){ctx.beginPath();ctx.moveTo(r.x+8,y);ctx.lineTo(r.x+r.w-8,y);ctx.stroke()}
