  rounded(r.x+8,r.y+8,r.w-16,23,8,'#fffdf4cc');ctx.fillStyle='#56665a';ctx.font='700 11px sans-serif';ctx.textAlign='left';ctx.fillText(`${r.emoji}  ${r.name}`,r.x+15,r.y+24);
}
