function drawPerson(p,emoji,label,isDad=false){
  ctx.save();ctx.translate(p.x,p.y);
  ctx.fillStyle='#24342b26';ctx.beginPath();ctx.ellipse(0,14,isDad?15:12,5,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle=isDad?'#4b6954':p.color;ctx.beginPath();ctx.roundRect(isDad?-11:-9,-1,isDad?22:18,22,7);ctx.fill();
  ctx.fillStyle=isDad?'#d7ad87':'#f1caa8';ctx.beginPath();ctx.arc(0,-8,isDad?9:8,0,Math.PI*2);ctx.fill();
  ctx.fillStyle=isDad?'#49382f':p.hair;ctx.beginPath();ctx.arc(0,-11,isDad?9:8,Math.PI,Math.PI*2);ctx.fill();
  ctx.fillStyle='#283734';ctx.font='700 8px sans-serif';ctx.textAlign='center';ctx.fillText(label,0,32);
  if(!isDad&&p.awake===false){ctx.font='17px sans-serif';ctx.fillText('💤',0,-27)}
  else {ctx.font='16px sans-serif';ctx.fillText(p.emoji||'😊',0,-27)}
  ctx.restore();
}
function draw(){
  ctx.clearRect(0,0,W,H);ctx.fillStyle='#d9dfcf';ctx.fillRect(0,0,W,H);
  rooms.forEach(drawRoom);
  // Cozy room furniture and useful stations
  drawProp(42,65,112,65,'#abc3a5','🛏️','Dad’s bed');drawProp(205,57,76,45,'#c7b497','🪟','window');
  drawProp(42,282,92,55,'#c7949a','🛏️','Elaina');drawProp(195,282,92,55,'#d59a9c','🛏️','Elsie');drawProp(94,408,100,55,'#e3b46b','🛏️','Ellerie');drawProp(208,485,80,54,'#c4a4b9','🧸','toy box');
  drawProp(354,54,78,78,'#b7d6d5','🚿','shower');drawProp(452,54,72,65,'#f5f5ec','🛁','bath');drawProp(359,166,72,58,'#b9d1c8','🧺','washer');drawProp(450,166,72,58,'#c8d2cf','🧺','dryer');
  drawProp(350,327,100,59,'#c99c68','🧊','fridge');drawProp(493,326,105,66,'#bb876e','🍳','stove');drawProp(429,425,114,65,'#d3b27e','🍽️','sink');drawProp(529,490,73,55,'#b99071','🪑','table');
  drawProp(666,72,130,67,'#8eaa8e','🛋️','sofa');drawProp(828,64,80,70,'#c0aa8d','📺','TV');drawProp(690,280,112,70,'#c2a887','🧸','toy pile');drawProp(832,447,76,65,'#a4bd9a','🐾','dog bed');
  // Subtle doorway markers join the rooms into one navigable house
  ctx.fillStyle='#b89d75';[[318,110],[318,405],[627,150],[627,430],[170,222],[170,238],[470,282],[470,298]].forEach(([x,y])=>{ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill()});
  const task=current();
  if(task){ctx.save();ctx.globalAlpha=.45+.25*Math.sin(performance.now()/220);ctx.strokeStyle='#d77b52';ctx.lineWidth=3;ctx.beginPath();ctx.arc(task.x,task.y,23,0,Math.PI*2);ctx.stroke();ctx.restore();ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText(task.emoji,task.x,task.y+7)}
  girls.forEach(g=>drawPerson(g,g.emoji,g.name));drawPerson(dad,'🙂','Dad',true);
  if(charlie.visible){ctx.font='29px sans-serif';ctx.textAlign='center';ctx.fillText('🐕',charlie.x,charlie.y+8);ctx.font='700 9px sans-serif';ctx.fillStyle='#435348';ctx.fillText('Charlie',charlie.x,charlie.y+25)}
  const room=zoneAt(dad.x,dad.y);$('roomtag').textContent=room?`${room.emoji} ${room.name}`:'🏠 HALLWAY';
  if(started&&!ended){const d=task?distance(dad,task):999;activeTarget=d<55?task:null;$('act').disabled=!activeTarget;$('act').innerHTML=activeTarget?`${task.emoji} ${task.label} <span class="key">E</span>`:'Interact&nbsp; <span class="key">E</span>';$('hint').innerHTML=activeTarget?`<b>${task.label}</b> — press E to get it done.`:`<b>${task?`Head to the ${task.room.toLowerCase()}`:'The house is settled'}</b> — ${task?`${task.emoji} ${task.label} is next.`:'everyone is tucked in.'}`}
  requestAnimationFrame(draw);
}
function renderUI(){
  const h=Math.floor(mins/60)%24,m=mins%60,ampm=h>=12?'PM':'AM',hour=h%12||12;
  $('clock').textContent=`${hour}:${String(m).padStart(2,'0')} ${ampm}`;
  $('phase').textContent=mins<720?'MORNING':mins<1020?'AFTERNOON':'EVENING';
  $('objective').textContent=choreIndex<chores.length?`${chores[choreIndex].emoji} ${chores[choreIndex].label} is next. ${choreIndex>=7?'The home stretch!':'One thing at a time, Dad.'}`:'The house is quiet. You made it through the day.';
  $('energybar').style.width=`${energy}%`; $('energylabel').textContent=`${Math.round(energy)}% ${energy>55?'okay':energy>25?'hanging in':'running low'}`;
  $('stressbar').style.width=`${stress}%`; $('stresslabel').textContent=`${Math.round(stress)}%`;
  $('tasks').innerHTML=chores.map((c,i)=>`<div class="task ${i<choreIndex?'done':''} ${i===choreIndex?'next':''}"><span class="check">${i<choreIndex?'✓':c.emoji}</span><span>${c.label}</span></div>`).join('');
  $('people').innerHTML=girls.map(g=>`<div class="person"><span class="avatar">${g.awake?g.emoji:'😴'}</span><span class="pname"><b>${g.name}</b><small>${g.awake?g.agenda:'still asleep'}</small></span><span class="focus"><i style="width:${g.focus}%"></i></span></div>`).join('');
}
function interact(){
  if(!started||ended)return;
  const task=current();if(!task||distance(dad,task)>55){say('A little closer, Dad — find the glowing spot.');return}
  if(task.id==='bedtime'&&mins<1200){say('Bedtime is at 8:00 PM. There’s still time for one more thing.');return}
  choreIndex++;helped++;energy=clamp(energy-7,0,100);stress=clamp(stress-5,0,100);
  say(task.desc);
  if(task.id==='bedtime'){
    girls.forEach(g=>{g.awake=false;g.goal=null;g.x=g.bed.x;g.y=g.bed.y+20;setMood(g,'sleepy','tucked in safely')});
    finish(true);return;
  }
  if(task.id==='showers')girls.forEach(g=>{if(g.awake){g.focus=clamp(g.focus+8,0,100);setMood(g,'happy','fresh from the shower')}});
  if(task.id==='laundry')charlie.nap=false;
  if(task.id==='tidy'&&distance(dad,charlie)<90){stress=clamp(stress+5,0,100);say('Charlie immediately redecorates with a slobbery toy.')}
  if(task.id==='breakfast'||task.id==='lunch'||task.id==='dinner')girls.forEach(g=>{if(g.awake){g.focus=clamp(g.focus+12,0,100);setMood(g,Math.random()<.35?'silly':'happy','eating (and negotiating seconds)')}});
  if(choreIndex===chores.length)finish(true);
  renderUI();
}
function finish(won){ended=true;$('ending').style.display='flex';$('endicon').textContent=won?'🌙':'🌧️';$('endtitle').textContent=won?'House is quiet.':'That was a lot for one day.';$('endcopy').textContent=won?`Everyone is tucked in, the dishes are done, and Dad kept his cool through ${temperOutbursts} outburst${temperOutbursts===1?'':'s'}. Nice work.`:'Dad needs a reset. Tomorrow is another chance to share the load and take more breathers.';$('endstats').innerHTML=`<span>✅ ${helped} tasks done</span><span>🌡️ ${temperOutbursts} outbursts</span><span>🧠 ${Math.round(energy)}% energy left</span>`}
function takeBreak(){if(!started||ended)return;mins+=10;energy=clamp(energy+27,0,100);stress=clamp(stress-12,0,100);say('Ten quiet minutes. Breathe in… breathe out. You’ve got this.');renderUI()}
function startGame(){if(started)return;started=true;$('intro').style.display='none';lastTick=performance.now();say('You stretch, get up, and start the day. Find the kitchen for breakfast!');renderUI()}
function tick(now){const dt=Math.min((now-lastTick)/1000,.1);lastTick=now;if(started&&!ended){gameSeconds+=dt;mins+=dt*3;
  energy=clamp(energy-dt*(.055+(keys.ArrowUp||keys.ArrowDown||keys.ArrowLeft||keys.ArrowRight||keys.w||keys.a||keys.s||keys.d?.05:0)),0,100);
  const overdue=choreIndex<chores.length&&mins>parseTime(chores[choreIndex].time)+35;
  stress=clamp(stress+dt*(overdue?1.35:.24)+(energy<18?dt*.35:0),0,100);
  if(stress>=100){temperOutbursts++;stress=38;energy=clamp(energy-18,0,100);say('Dad’s voice got a little too loud. Take a breath and try again.');if(temperOutbursts>=3)finish(false)}
  moveDad(dt);updateGirls(dt);if(gameSeconds%1<dt)renderUI();if(mins>1320&&choreIndex<chores.length&&chores[choreIndex].id!=='bedtime'){mins=1320;}
 }requestAnimationFrame(tick)}
function parseTime(t){let [h,m]=t.split(':').map(Number);if(h<7)h+=12;return h*60+m}
function moveDad(dt){let dx=0,dy=0;if(keys.ArrowLeft||keys.a||keys.A)dx--;if(keys.ArrowRight||keys.d||keys.D)dx++;if(keys.ArrowUp||keys.w||keys.W)dy--;if(keys.ArrowDown||keys.s||keys.S)dy++;if(dx||dy){let len=Math.hypot(dx,dy);dad.x=clamp(dad.x+dx/len*185*dt,27,W-27);dad.y=clamp(dad.y+dy/len*185*dt,27,H-27);dad.dir=dx<0?-1:dx>0?1:dad.dir;dad.walk+=dt*10}}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key==='e'||e.key==='E')interact()});window.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
$('start').addEventListener('click',startGame);$('restart').addEventListener('click',()=>location.reload());$('act').addEventListener('click',interact);$('mobileact').addEventListener('click',interact);$('break').addEventListener('click',takeBreak);
document.querySelectorAll('.mobilepad [data-dir]').forEach(btn=>{const dir=btn.dataset.dir,key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[dir];btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;btn.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,()=>keys[key]=false))});
$('sound').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='🔈'?'🔇':'🔈';say('A peaceful toggle. Sound effects are on their way!')});
renderUI();requestAnimationFrame(draw);requestAnimationFrame(tick);
</script>
