69	function finish(won){ended=true;$('ending').style.display='flex';$('endicon').textContent=won?'🌙':'🌧️';$('endtitle').textContent=won?'House is quiet.':'That was a lot for one day.';$('endcopy').textContent=won?`Everyone is tucked in, the dishes are done, and Dad kept his cool through ${temperOutbursts} outburst${temperOutbursts===1?'':'s'}. Nice work.`:'Dad needs a reset. Tomorrow is another chance to share the load and take more breathers.';$('endstats').innerHTML=`<span>✅ ${helped} tasks done</span><span>🌡️ ${temperOutbursts} outbursts</span><span>🧠 ${Math.round(energy)}% energy left</span>`}
70	function interact(){if(!started||ended)return;const task=current();if(!task||distance(dad,task)>55){say('A little closer, Dad — find the glowing spot.');return}if(task.id==='bedtime'&&mins<1200){say('Bedtime is at 8:00 PM. There’s still time for one more thing.');return}choreIndex++;helped++;energy=clamp(energy-7,0,100);stress=clamp(stress-5,0,100);say(task.desc);if(task.id==='bedtime'){girls.forEach(g=>{g.awake=false;g.goal=null;g.x=g.bed.x;g.y=g.bed.y+20;setMood(g,'sleepy','tucked in safely')});finish(true);return}if(task.id==='showers')girls.forEach(g=>{if(g.awake){g.focus=clamp(g.focus+8,0,100);setMood(g,'happy','fresh from the shower')}});if(task.id==='breakfast'||task.id==='lunch'||task.id==='dinner')girls.forEach(g=>{if(g.awake){g.focus=clamp(g.focus+12,0,100);setMood(g,Math.random()<.35?'silly':'happy','eating (and negotiating seconds)')}});if(task.id==='tidy'&&distance(dad,charlie)<90)stress=clamp(stress+5,0,100);renderUI()}
71	function takeBreak(){if(!started||ended)return;mins+=10;energy=clamp(energy+27,0,100);stress=clamp(stress-12,0,100);say('Ten quiet minutes. Breathe in… breathe out. You’ve got this.');renderUI()}
72	function startGame(){if(started)return;started=true;$('intro').style.display='none';lastTick=performance.now();say('You stretch, get up, and start the day. Find the kitchen for breakfast!');renderUI()}
73	function parseTime(t){let [h,m]=t.split(':').map(Number);if(h<7)h+=12;return h*60+m}
